def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    x = [float(v) for v in history if math.isfinite(float(v))]
    if horizon <= 0:
        return []
    if not x:
        return [0.0] * horizon
    max_p = min(168, len(x) // 2)
    best_p = None
    best_loss = float('inf')
    for p in range(2, max_p + 1):
        losses = []
        start = max(2 * p, len(x) - 3 * p)
        for t in range(start, len(x)):
            vals = [x[t - k * p] for k in range(1, 4) if t - k * p >= 0]
            if vals:
                losses.append(abs(x[t] - statistics.median(vals)))
        if losses:
            loss = sum(losses) / len(losses)
            if loss < best_loss:
                best_loss = loss
                best_p = p
    if best_p is None:
        return [float(statistics.median(x[-min(12, len(x)):]))] * horizon
    out = []
    n = len(x)
    for i in range(horizon):
        phase_index = n + i
        vals = [x[phase_index - k * best_p] for k in range(1, 5) if 0 <= phase_index - k * best_p < n]
        if not vals:
            vals = [out[i - best_p]] if i >= best_p else [x[-1]]
        out.append(float(statistics.median(vals)))
    return out
